class MaceATActionFactory(object):

    def __init__(self, mace):
        self._mace = mace
        self._at_executor = MaceAtCommandExecutor(mace)


class MacePreAttachFactory(MaceATActionFactory):

    def __init__(self, mace, config):
        super(MacePreAttachFactory, self).__init__(mace)
        self._config = config

    def create(self, deployment_mode):
        verifier = self._create_verifier(deployment_mode)
        inject_command_factory = self._create_inject_command_factory()

        if deployment_mode == DeploymentMode.SA:
            return SAPreAttach(at_executor=self._at_executor,
                               inject_command_factory=inject_command_factory,
                               config=self._config,
                               verifier=verifier)

        if deployment_mode == DeploymentMode.NSA:
            return NSAPreAttach(at_executor=self._at_executor,
                                inject_command_factory=inject_command_factory,
                                config=self._config,
                                verifier=verifier)

        if deployment_mode == DeploymentMode.LTE:
            return LTEPreAttach(at_executor=self._at_executor,
                                inject_command_factory=inject_command_factory,
                                config=self._config,
                                verifier=verifier)

        raise CreatePreAttachFailure("cannot create pre_attach in deployment mode {}".format(deployment_mode.value))

    def _create_inject_command_factory(self):
        return InjectCommandSetFactory(
            MaceGetSoftwareVersion(self._mace).execute(),
            MaceInjectMessageExecutor(self._mace)
        )

    def _create_verifier(self, deployment_mode):
        if deployment_mode == DeploymentMode.SA:
            return SAPreAttachUESideVerifier(mace_proxy=self._mace)
        if deployment_mode == DeploymentMode.NSA:
            return NSAPreAttachUESideVerifier(mace_proxy=self._mace)
        if deployment_mode == DeploymentMode.LTE:
            return LTEPreAttachUESideVerifier(mace_proxy=self._mace)
        raise CreateVerifierFailure("cannot create the verifier for pre_attach in deployment mode {}".
                                    format(deployment_mode.value))


