class MaceAttachFactory(MaceATActionFactory):

    def __init__(self, mace):
        super(MaceAttachFactory, self).__init__(mace)

    def create(self, deployment_mode):
        verifier = self._create_verifier(deployment_mode)

        if deployment_mode == DeploymentMode.SA:
            return SAAttach(executor=self._at_executor,
                            verifier=verifier)

        if deployment_mode == DeploymentMode.NSA:
            return NSAAttach(executor=self._at_executor,
                             verifier=verifier)

        if deployment_mode == DeploymentMode.LTE:
            return LTEAttach(executor=self._at_executor,
                             verifier=verifier)
        raise CreateAttachFailure("cannot create attach in deployment mode {}".format(deployment_mode.value))

    def _create_verifier(self, deployment_mode):
        if deployment_mode == DeploymentMode.SA:
            # return SAAttachUESideVerifier(mace_proxy=self._mace)
            return OTAMessageAlwaysPassVerifier(mace_proxy=self._mace)
        if deployment_mode == DeploymentMode.NSA:
            # return NSAAttachUESideVerifier(mace_proxy=self._mace)
            return OTAMessageAlwaysPassVerifier(mace_proxy=self._mace)
        if deployment_mode == DeploymentMode.LTE:
            return OTAMessageAlwaysPassVerifier(mace_proxy=self._mace)
        raise CreateVerifierFailure("cannot create the verifier for attach in deployment mode {}".
                                    format(deployment_mode.value))


