class MacePDNFactory(MaceATActionFactory):
    def __init__(self, mace, config):
        super(MacePDNFactory, self).__init__(mace)
        self._config = config

    def create(self, deployment_mode):
        verifier = self._create_verifier(deployment_mode)

        if deployment_mode == DeploymentMode.SA:
            return SAPDN(executor=self._at_executor,
                         config=self._config,
                         verifier=verifier)

        if deployment_mode == DeploymentMode.NSA:
            return NSAPDN(executor=self._at_executor,
                          config=self._config,
                          verifier=verifier)

        if deployment_mode == DeploymentMode.LTE:
            return LTEPDN(executor=self._at_executor,
                          config=self._config,
                          verifier=verifier)
        raise CreatePdnFailure("cannot create the pdn in deployment mode {}".
                               format(deployment_mode.value))

    def create_deactivate_additional_pdn(self, deployment_mode):
        verifier = self._create_verifier(deployment_mode)

        if deployment_mode == DeploymentMode.SA:
            return SADeactivateAdditionalPDN(executor=self._at_executor,
                                             config=self._config,
                                             verifier=verifier)

        if deployment_mode == DeploymentMode.NSA:
            return NSADeactivateAdditionalPDN(executor=self._at_executor,
                                              config=self._config,
                                              verifier=verifier)

        if deployment_mode == DeploymentMode.LTE:
            return LTEDeactivateAdditionalPDN(executor=self._at_executor,
                                              config=self._config,
                                              verifier=verifier)
        raise Exception("cannot create the additional pdn disconnection in deployment mode {}".
                        format(deployment_mode.value))

    def _create_verifier(self, deployment_mode):
        if deployment_mode == DeploymentMode.SA:
            return SAPDNUESideVerifier(self._mace)
        if deployment_mode == DeploymentMode.NSA:
            return NSAPDNUESideVerifier(self._mace)
        if deployment_mode == DeploymentMode.LTE:
            return LTEPDNUESideVerifier(self._mace)
        raise CreateVerifierFailure("cannot create the verifier for pdu session in deployment mode {}".
                                    format(deployment_mode.value))


class PetrusMacePDNFactory(MacePDNFactory):

    def __init__(self, mace, config):
        super(PetrusMacePDNFactory, self).__init__(mace, config)

    def create(self, deployment_mode):
        verifier = self._create_verifier(deployment_mode)

        if deployment_mode == DeploymentMode.SA:
            return PetrusSAPDN(executor=self._at_executor,
                               config=self._config,
                               verifier=verifier)

        elif deployment_mode == DeploymentMode.NSA:
            return PetrusNSAPDN(executor=self._at_executor,
                                config=self._config,
                                verifier=verifier)

        raise CreatePdnFailure("cannot create the Petrus pdn in deployment mode {}".
                               format(deployment_mode.value))

    def create_deactivate_additional_pdn(self, deployment_mode):
        verifier = self._create_deactivate_verifier(deployment_mode)

        if deployment_mode == DeploymentMode.SA:
            return PetrusSADeactivateAdditionalPDN(executor=self._at_executor,
                                                   config=self._config,
                                                   verifier=verifier)

        elif deployment_mode == DeploymentMode.NSA:
            return PetrusNSADeactivateAdditionalPDN(executor=self._at_executor,
                                                    config=self._config,
                                                    verifier=verifier)

        raise Exception("cannot create the Petrus additional pdn disconnection in deployment mode {}".
                        format(deployment_mode.value))

    def _create_deactivate_verifier(self, deployment_mode):
        if deployment_mode == DeploymentMode.SA:
            return PetrusSADeactivatePDNUESideVerifier(self._mace)

        elif deployment_mode == DeploymentMode.NSA:
            return PetrusNSADeactivatePDNUESideVerifier(self._mace)

        raise CreateVerifierFailure("cannot create the verifier for deactivating pdu session in deployment mode {}".
                                    format(deployment_mode.value))


class MaceEnableLoggingFactory(MaceATActionFactory):
    def __init__(self, mace, config):
        super(MaceEnableLoggingFactory, self).__init__(mace)
        self._config = config

    def create(self):
        log_filter_command = self._create_log_filter_command()
        return EnableLogging(at_executor=self._at_executor,
                             log_filter_command=log_filter_command,
                             config=self._config)

    def _create_log_filter_command(self):
        filter_name = self._config['log_filter'] or "2.Gen97_Default_Standard"
        return MaceSetDefaultFilter(self._mace, filter_name=filter_name)


class MaceRebootFactory(MaceATActionFactory):
    def __init__(self, mace):
        super(MaceRebootFactory, self).__init__(mace)

    def create(self):
        verifier = self._create_verifier()
        return Reboot(self._at_executor, verifier)

    def _create_verifier(self):
        return RebootVerifier(mace_proxy=self._mace)


class PetrusMaceRebootFactory(MaceRebootFactory):

    def _create_verifier(self):
        return PetrusRebootVerifier(mace_proxy=self._mace)


class MaceProxyFactory(object):
    def __init__(self, config, rpc):
        self._com = config['com_port']
        self._edb_file_path = config['edb_file_path']
        self._rpc = rpc

    def create(self):
        raw_proxy = self._rpc.create_proxy()
        params = {'raw': raw_proxy, 'port': self._com, 'edb_file_path': self._edb_file_path}
        return MaceProxy(**params)


class MaceVoiceCallFactory(MaceATActionFactory):

    def __init__(self, mace):
        super(MaceVoiceCallFactory, self).__init__(mace)

    def create(self, deployment_mode, name, ue_name, definition):
        if deployment_mode == DeploymentMode.SA:
            return MtkVoiceCall(name, ue_name, definition, at_executor=self._at_executor)
        raise UnsupportedDeploymentMode(deployment_mode)
